                starts.erase(starts.begin() + lo, starts.begin() + hi);
                ends.erase(ends.begin() + lo, ends.begin() + hi);
                starts.insert(starts.begin() + lo, ns.begin(), ns.end());
                ends.insert(ends.begin() + lo, ne.begin(), ne.end());
            }
