import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] starts, ends;
    static int size;

    static int lowerBound(long[] a, int len, long v) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (a[mid] < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(long[] a, int len, long v) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (a[mid] <= v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static void splice(int lo, int hi, int count, long s1, long e1, long s2, long e2) {
        int delta = count - (hi - lo);
        if (delta != 0) {
            System.arraycopy(starts, hi, starts, hi + delta, size - hi);
            System.arraycopy(ends, hi, ends, hi + delta, size - hi);
        }
        if (count >= 1) {
            starts[lo] = s1;
            ends[lo] = e1;
        }
        if (count >= 2) {
            starts[lo + 1] = s2;
            ends[lo + 1] = e2;
        }
        size += delta;
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int cq = (int) q;
        starts = new long[cq + 5];
        ends = new long[cq + 5];
        size = 0;
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < cq; t++) {
            long type = ops[t][0], l = ops[t][1], rr = ops[t][2];
            if (type == 3) {
                int i = upperBound(starts, size, l) - 1;
                if (out.length() > 0) out.append(" ");
                out.append(i >= 0 && ends[i] >= rr ? "YES" : "NO");
            } else if (type == 1) {
                int lo = lowerBound(ends, size, l), hi = upperBound(starts, size, rr);
                if (lo < hi) {
                    l = Math.min(l, starts[lo]);
                    rr = Math.max(rr, ends[hi - 1]);
                }
                splice(lo, hi, 1, l, rr, 0, 0);
            } else {
                int lo = upperBound(ends, size, l), hi = lowerBound(starts, size, rr);
                int count = 0;
                long s1 = 0, e1 = 0, s2 = 0, e2 = 0;
                if (lo < hi) {
                    if (starts[lo] < l) {
                        s1 = starts[lo];
                        e1 = l;
                        count = 1;
                    }
                    if (ends[hi - 1] > rr) {
                        if (count == 0) {
                            s1 = rr;
                            e1 = ends[hi - 1];
                        } else {
                            s2 = rr;
                            e2 = ends[hi - 1];
                        }
                        count++;
                    }
                    splice(lo, hi, count, s1, e1, s2, e2);
                }
            }
        }
        System.out.println(out);
    }
}
